<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Reports;final class ReportController{public function register():void{add_rewrite_rule('^healthcheck/report/([A-Za-z0-9_-]+)/?$','index.php?acorn_hc_report=$matches[1]','top');add_rewrite_tag('%acorn_hc_report%','([A-Za-z0-9_-]+)');add_action('template_redirect',[$this,'render']);}public function render():void{$token=(string)get_query_var('acorn_hc_report');if(!$token)return;$id=(new ReportAccess)->findAssessmentId($token);if(!$id){status_header(404);exit;}header('X-Robots-Tag: noindex, nofollow');header('Referrer-Policy: no-referrer');header('Cache-Control: private, no-store');$report=(new ReportDataBuilder)->build($id);require ACORN_HC_DIR.'templates/report-web.php';exit;}}
